/** Bentuk baris `listCatalogForAi` (sumber dealpos). `tagsFor(name)` -> [{ id, name }]. */
function catalogItems(tagsFor = () => []) {
  return ROWS.map(([code, name, category, brand, unit, price]) => ({
    id: code, kind: 'product', name, code, category, unit, price, priceNote: null, discountPct: 0,
    description: null, source: 'dealpos', brand, url: null, tags: tagsFor(name),
  }));
}

/** Bentuk baris `dealpos_products` (jalur harga tanpa katalog). */
function dealposProducts() {
  return ROWS.map(([code, name, category, , unit, price]) => ({ variantId: code, code, name, category, unit, unitPrice: price }));
}

module.exports = { catalogItems, dealposProducts };
